/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/company/treasuryStock.do",
        ref: "dma_loadListReq",
        target: "dlt_applicationList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil20301.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_113").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.viewTreasuryStock
 * @author Inswave
 * @date 2026. 09. 29
 * @param _flag
 * @returns
 * @hidden N
*/
scwin.viewTreasuryStock = async function (_flag) {
    /* sdd-asis-lifecycle:begin fn_ViewTreasuryStock — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.treasuryStockForm || { elements: [] });
    let methodVal = "";
    switch (_flag) {
        case 1:
        methodVal = "searchTreasuryStockDeclaration";
        break;
        case 2:
        methodVal = "searchTreasuryStockApplication";
        break;
        case 3:
        methodVal = "searchTreasuryStockTrading";
        break;
        case 4:
        methodVal = "searchTreasuryStockTradingDetail";
        break;
    }
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('method', methodVal);
    frm.action = "/company/treasuryStock.do";
    await scwin.tx_fn_ViewTreasuryStock();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.searchForm || { elements: [] });
    if ($c.util.getComponent('cal_sdate').getValue()> $c.util.getComponent('cal_edate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('excelTpCd', "N");
    $c.util.getComponent('dma_ViewTreasuryStockReq').set('method', "searchTreasuryStockApplication");
    frm.action = "/company/treasuryStock.do";
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


